package com.portafolio.dt.model;
import jakarta.persistence.*; import lombok.*; import java.time.*; import java.math.BigDecimal;
@Entity @Table(name="evidencias") @Getter @Setter @NoArgsConstructor @AllArgsConstructor public class Evidencia {  @Column(name="proyecto_id") Long proyectoId;  @Column(name="etapa_id") Long etapaId;  @Column(name="usuario_id") Long usuarioId;  @Enumerated(EnumType.STRING) @Column(name="tipo",columnDefinition="tipo_evidencia") TipoEvidencia tipo;  @Column(name="nombre_archivo") String nombreArchivo;  @Column(name="nombre_original") String nombreOriginal;  @Column(name="mime_type") String mimeType;  @Column(name="tamano_bytes") Long tamanoBytes;  @Column(name="ruta_archivo") String rutaArchivo;  @Column(name="url_archivo") String urlArchivo;  String descripcion;  @Column(name="creado_en") OffsetDateTime creadoEn; }